package io.github.diodeme.ji.extension;

import java.time.Instant;
import java.util.Objects;
import java.util.Optional;

/** Canonical project trust decisions bound to the complete protected-resource fingerprint. */
public interface ProjectTrustStore extends AutoCloseable {
    Optional<TrustDecision> find(ProjectIdentity project);

    TrustDecision decide(TrustCommand command);

    @Override
    default void close() {}

    record ProjectIdentity(String value, String canonicalRoot) {
        public ProjectIdentity {
            value = requireText(value, "project identity");
            canonicalRoot = requireText(canonicalRoot, "canonicalRoot");
        }
    }

    record ProjectFingerprint(String value) {
        public ProjectFingerprint {
            value = requireText(value, "project fingerprint");
            if (!value.matches("[0-9a-f]{64}")) {
                throw new IllegalArgumentException("project fingerprint must be lowercase SHA-256");
            }
        }
    }

    record TrustDecision(ProjectIdentity project, ProjectFingerprint fingerprint, Decision decision,
                         long revision, Instant decidedAt) {
        public static final TrustDecision UNTRUSTED = new TrustDecision(
                new ProjectIdentity("untrusted", "untrusted"),
                new ProjectFingerprint("0".repeat(64)), Decision.DENIED, 0, Instant.EPOCH);

        public TrustDecision {
            Objects.requireNonNull(project, "project");
            Objects.requireNonNull(fingerprint, "fingerprint");
            Objects.requireNonNull(decision, "decision");
            if (revision < 0) throw new IllegalArgumentException("revision must not be negative");
            Objects.requireNonNull(decidedAt, "decidedAt");
        }

        public boolean permits(ProjectIdentity candidateProject, ProjectFingerprint candidateFingerprint) {
            return decision == Decision.TRUSTED
                    && project.equals(candidateProject)
                    && fingerprint.equals(candidateFingerprint);
        }
    }

    record TrustCommand(ProjectIdentity project, ProjectFingerprint fingerprint, Decision decision,
                        long expectedRevision, Instant decidedAt) {
        public TrustCommand {
            Objects.requireNonNull(project, "project");
            Objects.requireNonNull(fingerprint, "fingerprint");
            Objects.requireNonNull(decision, "decision");
            if (expectedRevision < 0) throw new IllegalArgumentException("expectedRevision must not be negative");
            Objects.requireNonNull(decidedAt, "decidedAt");
        }
    }

    enum Decision { TRUSTED, DENIED }

    private static String requireText(String value, String name) {
        if (value == null || value.isBlank()) throw new IllegalArgumentException(name + " must not be blank");
        return value;
    }
}
